import {
  rollup,
  type CustomPluginOptions,
  type Plugin,
  type PluginContext,
  type ResolveIdResult,
} from "rollup";
import seismicPlugin from "../../src/seismic";

describe("Seismic plugin", () => {
  const testResolveId = async (
    source: string,
    importer?: string,
    options: {
      attributes: Record<string, string>;
      custom?: CustomPluginOptions;
      isEntry: boolean;
    } = {
      attributes: {},
      isEntry: false,
    },
  ): Promise<ResolveIdResult> => {
    const plugin: Plugin = seismicPlugin();
    if (typeof plugin.resolveId !== "function") {
      throw new Error("Plugin does not have a resolveId hook");
    }
    return await plugin.resolveId.call(
      {} as PluginContext,
      source,
      importer,
      options,
    );
  };

  test("should mark /uxasset/externals/@servicenow imports as external", async () => {
    expect(
      await testResolveId("/uxasset/externals/@servicenow/ui-core/index.jsdbx"),
    ).toEqual({
      external: true,
      id: "/uxasset/externals/@servicenow/ui-core/index.jsdbx",
      resolvedBy: "seismic",
    });
  });
  test("should mark /uxasset/externals/@devsnc imports as external", async () => {
    expect(
      await testResolveId("/uxasset/externals/@devsnc/library-uxf/index.jsdbx"),
    ).toEqual({
      external: true,
      id: "/uxasset/externals/@devsnc/library-uxf/index.jsdbx",
      resolvedBy: "seismic",
    });
  });
  test("should handle with attributes on imports", async () => {
    expect(
      await testResolveId("lodash", undefined, {
        isEntry: false,
        attributes: { external: "uxasset" },
      }),
    ).toEqual({
      external: true,
      id: "/uxasset/externals/lodash/index.jsdbx",
      attributes: {},
      resolvedBy: "seismic",
    });
  });
  test("end-to-end test with import attributes", async () => {
    // Virtual module plugin to provide inline module content
    const virtualPlugin: Plugin = {
      name: "virtual",
      resolveId(source) {
        if (source === "entry") return source;
        return null;
      },
      load(id) {
        if (id === "entry") {
          return `
import _ from 'lodash' with { external: "uxasset" };
import moment from 'moment' assert { external: "uxasset" };
import react from 'react' with { external: "uxasset" };
import 'sn-foobar-baz' assert { external: "uxasset" };

export default { _, moment, react };
`;
        }
        return null;
      },
    };

    const build = await rollup({
      input: "entry",
      plugins: [virtualPlugin, seismicPlugin()],
    });

    const { output } = await build.generate({ format: "es" });
    expect(output).toHaveLength(1);
    const outputModule = output[0];

    // Verify all imports are rewritten to uxasset paths
    expect(outputModule.imports).toContain(
      "/uxasset/externals/lodash/index.jsdbx",
    );
    expect(outputModule.imports).toContain(
      "/uxasset/externals/moment/index.jsdbx",
    );
    expect(outputModule.imports).toContain(
      "/uxasset/externals/react/index.jsdbx",
    );
    expect(outputModule.imports).toContain(
      "/uxasset/externals/sn-foobar-baz/index.jsdbx",
    );

    // Snapshot ensures: no assert/with statements, correct import paths
    expect(outputModule.code).toMatchSnapshot();
  });
  test("should ignore other imports", async () => {
    expect(await testResolveId("lodash")).toEqual(null);
  });
});
